import React, { useState } from 'react';
import './App.css';

function App() {
  const [count, setCount] = useState(1);
  const [amount, setAmount] = useState('');
  const [currency, setCurrency] = useState('');

  const handleIncrement = () => {
    setCount(count + 1);
    alert("Hello! Member1");
  };

  const handleDecrement = () => {
    setCount(count - 1);
  };

  const sayWelcome = () => {
    alert("welcome");
  };

  const handleClick = () => {
    alert("I was clicked");
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    const amt = parseFloat(amount);
    const cur = currency.toLowerCase();

    if (!amt || !cur) {
      alert("Please enter a valid amount and currency.");
      return;
    }

    let result;

    if (cur === "inr") {
      result = amt / 80;
      alert(`Converting from INR to Euro: €${result.toFixed(2)}`);
    } else if (cur === "euro") {
      result = amt * 80;
      alert(`Converting from Euro to INR: ₹${result.toFixed(2)}`);
    } else {
      alert("Unsupported currency. Use 'inr' or 'euro'.");
    }
  };

  return (
    <div className="container">
      <div className="counter">{count}</div>
      <div className="button-group">
        <button onClick={handleIncrement}>Increment</button>
        <button onClick={handleDecrement}>Decrement</button>
        <button onClick={sayWelcome}>Say welcome</button>
        <button onClick={handleClick}>Click on me</button>
      </div>

      <h1 className="heading">Currency Convertor!!!</h1>

      <form onSubmit={handleSubmit}>
        <div className="form-row">
          <label>Amount:</label>
          <input
            type="text"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
          />
        </div>
        <div className="form-row">
          <label>Currency:</label>
          <input
            type="text"
            value={currency}
            onChange={(e) => setCurrency(e.target.value)}
          />
        </div>
        <button type="submit" className="submit-btn">Submit</button>
      </form>
    </div>
  );
}

export default App;
